#!/usr/bin/env python3
"""Generate offline English fallbacks; --check verifies canonical JSON parity."""
import argparse
import json
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]


def generated():
    catalog = json.loads((ROOT/'data/languages.json').read_text(encoding='utf-8'))
    languages = catalog['languages']
    english = languages['en']
    python = ('# -*- coding: utf-8 -*-\n'
              '# Generated by tools/sync_languages.py; edit data/languages.json.\n'
              'from __future__ import unicode_literals\n\n'
              'ENGLISH = ' + repr(english) + '\n\nLEGACY_POLISH = ' + repr(languages['pl']) + '\n')
    js = '    // BEGIN GENERATED ENGLISH\n    var english = ' + json.dumps(english, ensure_ascii=True, sort_keys=True) + ';\n    // END GENERATED ENGLISH'
    path = ROOT/'ui/session_stats.js'
    source = path.read_text(encoding='utf-8')
    source, count = re.subn(r'    // BEGIN GENERATED ENGLISH\n.*?    // END GENERATED ENGLISH',
                            lambda unused: js, source, count=1, flags=re.S)
    if count != 1:
        raise RuntimeError('English fallback marker missing')
    return {ROOT/'src/grz_session_stats/language_defaults.py': python, path: source}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    for path, content in generated().items():
        if args.check:
            if not path.is_file() or path.read_text(encoding='utf-8') != content:
                raise RuntimeError('Generated translation fallback is stale: ' + path.name)
        else:
            path.write_text(content, encoding='utf-8')


if __name__ == '__main__':
    main()
